package com.obysoft.faithOS.service;
import java.time.*;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import com.obysoft.faithOS.dto.*;import com.obysoft.faithOS.entity.*;import com.obysoft.faithOS.exception.ResourceNotFoundException;import com.obysoft.faithOS.repository.AbsenceMotivationRepository;
@Service public class AbsenceService{private final AbsenceMotivationRepository repo;private final CurrentChurchService current;private final SensitiveDataService sensitive;private final int retentionDays;public AbsenceService(AbsenceMotivationRepository r,CurrentChurchService c,SensitiveDataService s,@org.springframework.beans.factory.annotation.Value("${app.retention.absence-days:365}")int days){repo=r;current=c;sensitive=s;retentionDays=days;}
 @Transactional public AbsenceResponse submit(AbsenceRequest req){User u=current.user();AbsenceMotivation a=new AbsenceMotivation();a.setChurch(u.getChurch());a.setUser(u);a.setAbsenceDate(req.absenceDate());a.setReason(sensitive.encrypt(req.reason().trim()));a.setExpiresAt(LocalDateTime.now().plusDays(retentionDays));return response(repo.save(a));}
 @Transactional(readOnly=true)public List<AbsenceResponse> mine(){return repo.findAllByUserIdOrderByCreatedAtDesc(current.user().getId()).stream().map(this::response).toList();}
 @Transactional(readOnly=true)public List<AbsenceResponse> church(){return repo.findAllByChurchIdOrderByCreatedAtDesc(current.church().getId()).stream().map(this::response).toList();}
 @Transactional public AbsenceResponse acknowledge(Long id){AbsenceMotivation a=repo.findByIdAndChurchId(id,current.church().getId()).orElseThrow(()->new ResourceNotFoundException("Absence motivation not found."));a.setStatus("ACKNOWLEDGED");a.setReviewedAt(LocalDateTime.now());a.setReviewedBy(current.user());return response(repo.save(a));}
 private AbsenceResponse response(AbsenceMotivation a){User u=a.getUser();return new AbsenceResponse(a.getId(),u.getId(),u.getFirstName()+" "+u.getLastName(),a.getAbsenceDate(),sensitive.decrypt(a.getReason()),a.getStatus(),a.getCreatedAt(),a.getReviewedAt());}}
